#include <iostream>
using namespace std;

void printInt128(__int128 value) {
    if (value == 0) {
        cout << "0\n";
        return;
    }
    if (value < 0) {
        cout << '-';
        value = -value;
    }
    string result;
    while (value > 0) {
        result += char('0' + value % 10);
        value /= 10;
    }
    for (auto it = result.rbegin(); it != result.rend(); ++it)
        cout << *it;
    cout << '\n';
}

int main() {
    long long x1, x2, x3, x4;
    cin >> x1 >> x2 >> x3 >> x4;

    __int128 a = x1, b = x2, c = x3, d = x4;

    if (b - a == c - b && c - b == d - c) {
        printInt128(d + (b - a));
    } else if (a != 0 &&
               b * b == a * c &&
               b * c == a * d &&
               (d * b) % a == 0) {
        printInt128((d * b) / a);
    } else {
        cout << "42\n";
    }

    return 0;
}

